sql.where:
management_items.management_item_code is not null

    and settings.area_code = #{criteria.normalizedAchievementAreaCode}


    and items.item_code = #{criteria.normalizedAchievementCategoryCode}


    and settings.college_code = #{criteria.normalizedCollegeCode}

mapper.select:
select exists(
    select 1
    from evaluation_areas areas
    inner join evaluation_items items on items.area_id = areas.area_id
    inner join evaluation_elements elements on elements.item_id = items.item_id
    inner join evaluation_management_items management_items on management_items.element_id = elements.element_id
    where areas.rule_version_id = #{ruleVersionId}
      and areas.area_code = #{achievementAreaCode}
      and items.item_code = #{achievementCategoryCode}
      and management_items.management_item_code = #{managementItemCode}
)

select 

where settings.rule_version_id = #{ruleVersionId}
  and settings.evaluation_year = #{evaluationYear}
  and settings.area_code = #{achievementAreaCode}
  and settings.management_item_code = #{managementItemCode}
  and settings.college_code = #{collegeCode}
limit 1
